void*operator new(std::size_t n){if(tracking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
int main(){try{tracking=true;Config c;
 for(unsigned e=0;e<65536;++e){c=Config{};c.count=1;c.events[0]=uint16_t(e);c.bias=uint8_t(e>>8);c.flags=uint8_t(e);c.mode=uint8_t(e>>8);c.consumer=uint16_t(e&510);c.queueProducer=c.serialProducer=uint16_t(e&255);run(c);}
 for(unsigned flags=0;flags<256;++flags)for(unsigned mode:{0u,63u,64u,255u})for(unsigned part:{0u,3u,255u}){c=Config{};c.flags=uint8_t(flags);c.mode=uint8_t(mode);c.part=uint8_t(part);c.channel=uint8_t(flags);run(c);}
 for(unsigned index=0;index<256;++index)for(unsigned position=0;position<256;position+=17){c=Config{};c.queueProducer=c.serialProducer=uint16_t(index);c.queueConsumer=uint16_t(position);c.consumer=uint16_t(2*position);run(c);}
 for(int history:{-1,0x17525,0x15b07,0x15b08,0x15b09,0xffed6d,0xffff89}){c=Config{};c.history=history;run(c);}c=Config{};c.fullSerial=true;run(c);c=Config{};c.live=true;run(c);c=Config{};c.count=0;run(c);c=Config{};c.count=4;c.events={{0x6410,0xc010,0x001a,0x7f20}};run(c);
 tracking=false;check(!allocations&&components==0x1ff&&waits==1,"Upper-State graph/allocation coverage incomplete");std::printf("PASS: %llu pure Controls graphs; %llu phases; %llu rejected budgets; %llu packet bytes; components=%x; full UART waits=%llu; no allocations; all event bytes, modes/local flags, part/channel bytes, rings/wrap, live resources and exact callbacks verified\n",(unsigned long long)cases,(unsigned long long)phases,(unsigned long long)rejected,(unsigned long long)packets,components,(unsigned long long)waits);return 0;}catch(const std::exception&e){tracking=false;std::fprintf(stderr,"%s\n",e.what());return 1;}}
